import io.heapy.kotdoc.crypto.*;import java.math.BigInteger;
class RsaRootReview {public static void main(String[] a){var rsa=new CryptoRsa(new CryptoNumberPrime(new CryptoProbabilistic(n->new byte[n])));try{rsa.generateBlinder(BigInteger.ZERO,n->new byte[n]);System.out.println("returned Blinder root");}catch(Exception e){System.out.println(e.getMessage());}try{var g=CryptoChaChaDrg.Companion.initialize(new byte[40]);var action=rsa.generateBlinderAction(kotlin.LazyKt.lazyOf(BigInteger.ZERO),CryptoChaChaDrg.Companion.getOperations());CryptoRandom.INSTANCE.withDRG(g,action).getFirst().getValue();System.out.println("returned action Blinder root");}catch(Exception e){System.out.println(e.getMessage());}}}
